def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0].strip())
    idx = 1

    results = []
    for _ in range(t):
        if idx >= len(lines):
            break

        # Parse dimensions
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        if idx >= len(lines):
            break

        n, m = map(int, lines[idx].split())
        idx += 1

        # Read matrix and compute XOR sum
        xor_sum = 0
        for i in range(n):
            if idx >= len(lines):
                break
            row = list(map(int, lines[idx].split()))
            idx += 1
            for val in row:
                if val > 0:
                    xor_sum ^= val

        if xor_sum != 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

