import math

def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        operations.append((t, x_prime, y))

    # reachable[v] = earliest step when value v can be achieved
    reachable = [-1] * (m + 1)
    reachable[0] = 0  # Initially 0 bananas at step 0

    for step, (t, x_prime, y) in enumerate(operations):
        step += 1  # Convert to 1-indexed step

        x_num = x_prime
        x_den = 100000

        # Consider all values that were reachable before this step
        for v in range(m + 1):
            if reachable[v] >= 0:
                if t == 1:
                    # Type 1: k := ceil(k + a * x) applied up to y times
                    # After a applications: ceil(v + a * x_num/x_den)
                    for a in range(y + 1):
                        val = v * x_den + a * x_num
                        new_v = math.ceil(val / x_den)
                        if new_v <= m:
                            if reachable[new_v] == -1 or step < reachable[new_v]:
                                reachable[new_v] = step

                elif t == 2:
                    # Type 2: k := ceil(k * x) applied up to y times
                    # Note: repeated ceiling multiplication
                    current = v
                    for a in range(y + 1):
                        if a > 0:
                            current = math.ceil(current * x_num / x_den)
                        elif current <= m:
                            if reachable[current] == -1 or step < reachable[current]:
                                reachable[current] = step
                        if current <= m:
                            if reachable[current] == -1 or step < reachable[current]:
                                reachable[current] = step

    # Format output as space-separated integers from 1 to m
    result = ' '.join(str(reachable[i]) for i in range(1, m + 1))
    return '\n' + result + '\n'

