    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            q = [i]
            visited[i] = True
            size = 0
            idx = 0
            while idx < len(q):
                node = q[idx]
                idx += 1
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        q.append(neighbor)
            component_sizes.append(size)

    # Check if any component size is lucky
    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    for size in component_sizes:
        if is_lucky(size):
            return "0"

    # Generate all lucky numbers up to n using DFS
    lucky_numbers = set()
    lucky_candidates = []

    def generate_lucky(current, length):
        if current > n:
            return
        lucky_numbers.add(current)
        lucky_candidates.append(current)
        if len(current) < len(str(n + 1)):
            generate_lucky(current * 10 + 4, length + 1)
            generate_lucky(current * 10 + 7, length + 1)

    generate_lucky(4, 1)
    generate_lucky(7, 1)

    # Sort by number of components needed and by value
    lucky_candidates_sorted = sorted(lucky_candidates)

    # DP: dp[s] = minimum number of components to achieve sum s
    # Initialize with dp[0] = 0 (zero components needed for sum 0)
    dp = {0: 0}

    for size in component_sizes:
        new_dp = dict(dp)
        for prev_sum, count in dp.items():
            new_sum = prev_sum + size
            if new_sum > n:
                continue
            new_count = count + 1
            if new_sum not in new_dp or new_count < new_dp[new_sum]:
                new_dp[new_sum] = new_count
        dp = new_dp

    # Find minimum component count for any lucky number
    min_components = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp:
            min_components = min(min_components, dp[lucky])

    if min_components == float('inf') or min_components < 1:
        return "-1"

    return str(min_components - 1)

