from typing import List

def is_palindrome_rearrangeable(s: str) -> bool:
    """Check if a string can be rearranged to form a palindrome."""
    count = {}
    for ch in s:
        count[ch] = count.get(ch, 0) + 1
    odds = sum(1 for v in count.values() if v % 2 == 1)
    return odds <= 1  # At most one character can have odd frequency

def can_beautiful(matrix: List[List[str]], r1: int, c1: int, r2: int, c2: int) -> bool:
    """Check if the submatrix can be beautiful after reordering rows."""
    h = r2 - r1 + 1
    w = c2 - c1 + 1

    # Collect all characters from the submatrix
    all_chars = []
    for r in range(r1, r2 + 1):
        for c in range(c1, c2 + 1):
            all_chars.append(matrix[r][c])

    # Check if each row can be rearranged as a palindrome
    for r in range(r1, r2 + 1):
        row_str = ''.join(matrix[r][c] for c in range(c1, c2 + 1))
        if not is_palindrome_rearrangeable(row_str):
            return False

    # Check if each column can be rearranged as a palindrome considering subset
    for c in range(c1, c2 + 1):
        col_chars = []
        for r in range(r1, r2 + 1):
            col_chars.append(matrix[r][c])
        col_str = ''.join(col_chars)
        if not is_palindrome_rearrangeable(col_str):
            return False

    return True

