def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0\n"

    # Limit for finding base primes
    limit = int(math.isqrt(r)) + 1
    primes = []
    is_prime_small = [True] * (limit + 1)

    # Sieve to find primes up to sqrt(r)
    for i in range(2, limit + 1):
        if is_prime_small[i]:
            primes.append(i)
            for j in range(i * i, limit + 1, i):
                is_prime_small[j] = False

    size = r - l + 1
    # Use array for memory efficiency
    is_prime_range = array.array('b', [1] * size)
    count = 0

    # Segmented sieve: mark non-primes in [l, r]
    for p in primes:
        if p * p > r:
            break
        # First multiple of p >= l
        start = ((l + p - 1) // p) * p
        # Start from p*p to avoid marking primes
        start = max(p * p, start)
        for j in range(start, r + 1, p):
            is_prime_range[j - l] = 0

    # Count qualifying primes (p = 2 or p % 4 == 1)
    for i in range(l, r + 1):
        if is_prime_range[i - l] == 1:
            # Verify it's a prime (double check boundary conditions)
            if i < 2:
                continue
            # Check if it satisfies the lucky condition
            if i == 2 or i % 4 == 1:
                count += 1

    return str(count) + "\n"

