def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    v = list(map(int, lines[1].split()))
    c = list(map(int, lines[2].split()))

    if n == 0 or k > n:
        return "0.0"

    # Build sparse table for range maximum queries on v
    # Build sparse table for range minimum queries on c
    LOG = max(1, n.bit_length())

    # Range maximum for visitors
    st_v = [[0] * n for _ in range(LOG)]
    for i in range(n):
        st_v[0][i] = v[i]

    for j in range(1, LOG):
        for i in range(n - (1 << j) + 1):
            st_v[j][i] = max(st_v[j-1][i], st_v[j-1][i + (1 << (j-1))])

    # Range minimum for costs
    st_c = [[0] * n for _ in range(LOG)]
    for i in range(n):
        st_c[0][i] = c[i]

    for j in range(1, LOG):
        for i in range(n - (1 << j) + 1):
            st_c[j][i] = min(st_c[j-1][i], st_c[j-1][i + (1 << (j-1))])

    def query_max(l, r):
        length = r - l + 1
        j = (length).bit_length() - 1
        return max(st_v[j][l], st_v[j][r - (1 << j) + 1])

    def query_min(l, r):
        length = r - l + 1
        j = (length).bit_length() - 1
        return min(st_c[j][l], st_c[j][r - (1 << j) + 1])

    # For each starting position, find the best ending position
    best = [0] * n
    for i in range(n):
        best_val = 0
        for r in range(i, n):
            mv = query_max(i, r) * 100
            mc = query_min(i, r)
            pot = min(mv, mc)
            if pot > best_val:
                best_val = pot
        best[i] = best_val

    # Sort the best values
    best.sort()

    # Precompute factorials
    f = [1] * (n + 1)
    for i in range(2, n + 1):
        f[i] = f[i-1] * i

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return f[n] // (f[k] * f[n-k])

    # Compute expected minimum of k values from n sorted values
    # Formula: E = (1/C(n,k)) * sum_{j=0}^{n-k} best[j] * C(n-j-1, k-1)
    total = 0
    for j in range(n - k + 1):
        total += best[j] * C(n - j - 1, k - 1)

    expected = total / C(n, k)
    return f"{expected:.10f}"

