    cap_edges = []
    other_edges = []

    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
        edge = (w, a, b, i)
        if a == 1 or b == 1:
            cap_edges.append(edge)
        else:
            other_edges.append(edge)

    cap_edges.sort()
    other_edges.sort()

    # Check if k is feasible
    if k > n - 1 or k > len(cap_edges):
        return "-1"

    def find(p, x):
        if p[x] == x:
            return x
        p[x] = find(p, p[x])
        return p[x]

    def union(p, r, x, y):
        rx, ry = find(p, x), find(p, y)
        if rx == ry:
            return False
        if r[rx] < r[ry]:
            p[rx] = ry
        elif r[rx] > r[ry]:
            p[ry] = rx
        else:
            p[rx] = ry
            r[ry] += 1
        return True

    def is_capital(edge_idx):
        for w, a, b, idx in cap_edges:
            if idx == edge_idx:
                return True
        return False

    def count_capitals(selected_indices):
        return sum(1 for idx in selected_indices if is_capital(idx))

    # Try different numbers of capital edges from 0 to k
    for num_capital_needed in range(min(k, len(cap_edges)) + 1):
        p = list(range(n + 1))
        r = [0] * (n + 1)
        selected = []
        capital_used_count = 0

