        for w, a, b, idx in cap_edges:
            if union(p, r, a, b):
                selected.append(idx)
                capital_used_count += 1

        # Fill with other edges
        for w, a, b, idx in other_edges:
            if union(p, r, a, b):
                selected.append(idx)

        # Check connectivity and capital count
        root = find(p, 1)
        connected = all(find(p, i) == root for i in range(1, n + 1))
        actual_capitals = count_capitals(selected)

        if connected and actual_capitals == k:
            return str(len(selected)) + "\n" + " ".join(map(str, selected)) + "\n"

    # If we couldn't find a solution with the right cast
