        """Check if there's any light visible in the given direction."""
        for k in range(1, n):
            nx, ny = x + dx * k, y + dy * k
            if 0 <= nx < n and 0 <= ny < n:
                if grid[nx][ny] == 1:
                    return True
            else:
                break
        return False

    def backtrack(x, y, lit_count, visited, result):
        if lit_count == 0:
            # Return to start
            stack = [(x, y)]
            curr_x, curr_y = x, y

            while (curr_x, curr_y) != (x0, y0):
