        original_val = grid[x][y]
        grid[x][y] = 0

        visited.add((x, y))

        for i, (dchar, dx, dy) in enumerate(directions):
            if is_visible(x, y, dx, dy):
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    result.append(dchar)
