                    visited.remove((nx, ny))
                    result.pop()

        # Backtrack
        visited.remove((x, y))
        grid[x][y] = original_val
        result.pop()

        return False

    result = []
    if backtrack(x0, y0, initial_lit, set(), result):
        return "YES\n" + "".join(result)
    else:
