        for i in range(n):
            for j in range(m):
                if grid[i][j] != 0:
                    for di in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if di == 0 and dc == 0:
                                continue
                            ni, nj = i + di, j + dc
                            if 0 <= ni < n and 0 <= nj < m:
                                if grid[ni][nj] == grid[i][j]:
