def solve(a, b, n, memo=None):
    if memo is None:
        memo = {}

    state = (a, b)
    if state in memo:
        return memo[state]

    # Check if current state is valid
    if a**b >= n:
        # This shouldn't happen based on problem guarantee for starting state
        # but if we reach here, game is already over with previous player losing
        return True  # Current player already lost

    # Generate valid moves
    moves = []
    if (a + 1) ** b < n:
        moves.append((a + 1, b))
    if a ** (b + 1) < n:
        moves.append((a, b + 1))

    if not moves:
        # No valid moves, current player loses
        memo[state] = True
        return True

    # Check if opponent loses from any reachable position
    can_win = False
    for new_a, new_b in moves:
        if not solve(new_a, new_b, n, memo):
            can_win = True
            break

    memo[state] = not can_win
    return not can_win

