import operator
from collections import Counter
from itertools import combinations

def solution(input_str):
    parts = input_str.split('\n')
    n, m = map(int, parts[0].split())

    A = []
    line_idx = 1
    for i in range(n):
        A.append(list(map(int, parts[line_idx].split())))
        line_idx += 1

    B = []
    for i in range(n):
        B.append(list(map(int, parts[line_idx].split())))
        line_idx += 1

    # Check if A and B have the same multiset of rows
    if list(sorted(A)) != list(sorted(B)):
        return "-1"

    # No columns needed
    if A == B:
        return "0"

    # Try sorting by columns
    for col in range(m):
        A_copy = [row[:] for row in A]
        if A_copy == B:
            return "0"

        A_copy.sort(key=operator.itemgetter(col))
        if A_copy == B:
            return f"1\n{col + 1}"

    # Try combinations (limited to avoid TLE)
    for r in range(2, min(m + 1, 12)):
        for cols in combinations(range(m), r):
            A_copy = [row[:] for row in A]
            for c in cols:
                A_copy.sort(key=operator.itemgetter(c))

            if A_copy == B:
                return f"{r}\n" + " ".join(str(c + 1) for c in cols)

    return "-1"

def solution(input_data):
    # Parse the input
    lines = input_data.strip().split('\n')
    n = int(lines[0])

    # Store query queries and their parameters
    queries = []
    idx = 1
    for i in range(n):
        if idx < len(lines):
            parts = lines[idx].split()
            idx += 1
            t = int(parts[0])
            if t == 1:
                a = int(parts[1])
                b = int(parts[2])
                queries.append(('add', a, b, i + 1))  # 1-based index
            elif t == 2:
                rem_idx = int(parts[1])
                queries.append(('remove', rem_idx, i + 1))
            elif t == 3:
                q_val = int(parts[1])
                queries.append(('query', q_val, i + 1))

    # All add queries so far
    add_queries = []
    for i, q in enumerate(queries):
        if q[0] == 'add':
            add_queries.append(q)

    # Remove queries (store which query to remove)
    remove_queries = []
    for i, q in enumerate(queries):
        if q[0] == 'remove':
            remove_queries.append(q)

    # All query type 3
