def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n+1):
        matrix.append(list(map(int, lines[i].split())))

    # Count factors of 2 and 5 in each number
    def count_factors(x):
        if x == 0:
            return float('inf'), float('inf')  # Path through 0 gives infinite trailing zeros
        c2 = 0
        while x > 0 and x % 2 == 0:
            c2 += 1
            x //= 2
        c5 = 0
        while x > 0 and x % 5 == 0:
            c5 += 1
            x //= 5
        return c2, c5

    # Precompute 2s and 5s for each cell
    num_2 = [[0]*n for _ in range(n)]
    num_5 = [[0]*n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            num_2[i][j], num_5[i][j] = count_factors(matrix[i][j])

    # dp[i][j] = list of (c2, c5) pairs that are Pareto-optimal for reaching (i,j)
    # A pair (a,b) dominates (c,d) iff a<=c and b<=d (at least one strict)
    dp = [[[] for _ in range(n)] for _ in range(n)]
    dp[0][0].append((num_2[0][0], num_5[0][0]))

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            candidates = []
            if i > 0:
                for c2, c5 in dp[i-1][j]:
                    candidates.append((c2 + num_2[i][j], c5 + num_5[i][j]))
            if j > 0:
                for c2, c5 in dp[i][j-1]:
                    candidates.append((c2 + num_2[i][j], c5 + num_5[i][j]))

            # Filter to keep only non-dominated states
            filtered = []
            for cand in candidates:
                dominated = False
                for existing in filtered:
                    if existing[0] <= cand[0] and existing[1] <= cand[1]:
                        dominated = True
                        break
                if not dominated:
                    for idx, existing in enumerate(filtered):
                        if cand[0] <= existing[0] and cand[1] <= existing[1]:
                            if cand[0] < existing[0] or cand[1] < existing[1]:
                                filtered[idx] = cand
                            break
                    else:
                        filtered.append(cand)
            dp[i][j] = filtered

    # Find minimum trailing zeros at bottom-right
    min_trailing = float('inf')
    for c2, c5 in dp[n-1][n-1]:
        min_trailing = min(min_trailing, min(c2, c5))

    # Backtrack to reconstruct the path
    path = []
    i, j = n - 1, n - 1

    # Pick optimal state at bottom-right
    target_c2, target_c5 = None, None
    for c2, c5 in dp[n-1][n-1]:
        if min(c2, c5) == min_trailing:
            target_c2, target_c5 = c2, c5
            break

    while i > 0 or j > 0:
        if i > 0 and j > 0:
            from_top = (target_c2 - num_2[i-1][j], target_c5 - num_5[i-1][j]) in dp[i-1][j]
            from_left = (target_c2 - num_2[i][j-1], target_c5 - num_5[i][j-1]) in dp[i][j-1]

            if from_top and not from_left:
                path.append('R')
                target_c2 -= num_2[i-1][j]
                target_c5 -= num_5[i-1][j]
                i -= 1
            elif from_left and not from_top:
                path.append('D')
                target_c2 -= num_2[i][j-1]
                target_c5 -= num_5[i][j-1]
                j -= 1
            else:
                path.append('R')
                target_c2 -= num_2[i-1][j]
                target_c5 -= num_5[i-1][j]
                i -= 1
        elif i > 0:
            path.append('R')
            target_c2 -= num_2[i-1][j]
            target_c5 -= num_5[i-1][j]
            i -= 1
        else:
            path.append('D')
            target_c2 -= num_2[i][j-1]
            target_c5 -= num_5[i][j-1]
            j -= 1

    path.reverse()
    return str(min_trailing) + '\n' + ''.join(path)

