def check_partition(A, r, c):
    """Check if all r×c blocks in partition are identical."""
    n = len(A)
    m = len(A[0])

    # Extract and compare all blocks
    blocks = []
    for i in range(0, n, r):
        for j in range(0, m, c):
            b = []
            for di in range(r):
                for dj in range(c):
                    b.append(A[i + di][j + dj])
            blocks.append(tuple(b))

    return len(set(blocks)) == 1 if blocks else True

