    """
    Determine if all r×c partition blocks are equal.
    Two blocks are equivalent if their flattened values match.
    """
    h, w = len(grid), len(grid[0])

    # Build reference from top-left
    ref = [grid[0][0] for _ in range(w))
    for di in range(1, r):
