    n, m = int(first_line[0]), int(first_line[1])
    edges = []
    for i in range(m):
        if 1 + i < len(lines):
            line = lines[1 + i].split()
            if len(line) >= 2:
                edges.append((int(line[0]), int(line[1]), i))

    def check_crossing(e1, e2):
        a1, b1, _ = e1
        a2, b2, _ = e2

        # If they share a vertex, they meet at an endpoint (allowed)
        # but we need to check if they cross elsewhere
        # Actually for crossing detection on a cycle, shared vertex paths
        # don't cross if endpoints aren't interleaved

        # Normalize so a < b for each edge
        if a1 > b1:
            a1, b1 = b1, a1
        if a2 > b2:
            a2, b2 = b2, a2

        # Check if endpoints interleave
        def in_interval(start, end, x):
            return start < x < end

        # Edge1 spans (a1,b1), Edge2 spans (a2,b2)
        # They cross if one of Edge2's endpoints is in (a1,b1) XOR the other is
        return (in_interval(a1, b1, a2) and not in_interval(a1, b1, b2)) or \
               (in_interval(a2, b2, a1) and not in_interval(a2, b2, b1))

    # Build constraint graph: edges that cross must have different values
    # 0 = 'i' (inside), 1 = 'o' (outside)
    constraints = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if check_crossing(edges[i], edges[j]):
                constraints[i].append(j)
                constraints[j].append(i)

    visited = [False] * m
    assignment = [None] * m

    # BFS from each unvisited component
    for start in range(m):
        if visited[start]:
            continue

        queue = [start]
        visited[start] = True
        assignment[start] = 0

        while queue:
            curr = queue.pop(0)

            for neighbor in constraints[curr]:
                if assignment[neighbor] is None:
                    # Not assigned yet, assign opposite value
                    assignment[neighbor] = 1 - assignment[curr]
                    visited[neighbor] = True
                    queue.append(neighbor)
                else:
                    # Already assigned - check for conflict
                    if assignment[neighbor] == assignment[curr]:
                        return "Impossible"

    # Build result string
    result = []
    for i in range(m):
        if assignment[i] is None:
            result.append('o')  # Default to outside for unassigned
        else:
            result.append('i' if assignment[i] == 0 else 'o')

    return ''.join(result)

