                    if ans[1] == 'L' and p[1] >= 1:
                        continue
                    return False
                elif i == n - 1:
                    # Lantern n-1 only needs illumination from lantern n-2 going right
                    if ans[n-2] == 'R' and p[n-2] >= 1:
                        continue
                    return False
                else:
                    # Lantern i needs illumination from either side
                    from_left = (ans[i-1] == 'R' and p[i-1] >= 1)
                    from_right = (ans[i+1] == 'L' and p[i+1] >= 1)
                    if not from_left and not from_right:
                        return False
